import 'package:flutter/material.dart';import 'package:get/get.dart';import '../../app_routes.dart';import '../../models/conversation.dart';import 'chat_controller.dart';
class ConversationListPage extends GetView<ChatController>{const ConversationListPage({super.key});@override Widget build(BuildContext context){controller.loadConversations();return Scaffold(appBar:AppBar(title:const Text('Chats')),body:Obx(()=>controller.loading.value?const Center(child:CircularProgressIndicator()):ListView.separated(itemCount:controller.conversations.length,separatorBuilder:(_,__)=>const Divider(height:1,indent:72),itemBuilder:(context,index){final c=controller.conversations[index];return ListTile(leading:CircleAvatar(child:Icon(c.kind==ConversationKind.direct?Icons.person:Icons.group)),title:Text(c.title),subtitle:Text(c.lastMessagePreview??'No messages',maxLines:1,overflow:TextOverflow.ellipsis),trailing:c.unreadCount==0?null:Badge(label:Text('${c.unreadCount}')),onTap:()=>Get.toNamed(AppRoutes.conversation.replaceFirst(':id',c.id),parameters:{'title':c.title});}))));}}
